import React from 'react';
import { Link } from 'react-router-dom';
import styles from '../FpcPlaceholderPage.module.css';

const FEATURE = 'du-kien-chi';
const TITLE = 'Dự kiến chi theo ngày';
const ROUTE = '/tc/kh/du-kien-chi';
const DEMO = '/demo/kh/khai-bao-chi-phi';

/**
 * Chứng từ placeholder — clone từ FpcCostDeclarePage via `/implement-kpi`.
 * Cấm sửa demo.
 */
export default function CostDeclarePlaceholder() {
  const testId = 'fpc-placeholder-du-kien-chi';

  return (
    <div className={styles.page} data-testid={`${testId}-page`} data-lin-page-id={FEATURE}>
      <header className={styles.header}>
        <div className={styles.titleBlock}>
          <div className={styles.titleRow}>
            <i className={`fas fa-file-invoice-dollar ${styles.titleIcon}`} aria-hidden />
            <h1 className={styles.title}>{TITLE}</h1>
          </div>
          <p className={styles.subtitle}>
            Placeholder — clone UI từ demo «{TITLE}» khi chạy{' '}
            <code>/implement-kpi --feature {FEATURE}</code>
          </p>
        </div>
        <div className={styles.badges}>
          <span className={`${styles.badge} ${styles.badgePhase}`}>P0</span>
          <span className={`${styles.badge} ${styles.badgeStatus}`}>Chưa implement</span>
        </div>
      </header>

      <section className={styles.card} data-testid={`${testId}-card`}>
        <h2 className={styles.cardTitle}>Sẵn sàng cho /implement-kpi</h2>
        <p className={styles.cardBody}>
          Chứng từ L1 — giữ route + menu. Khi implement: AskQuestion <code>demo_form_ref</code> = Dự
          kiến chi → clone demo (cấm sửa) → chuẩn hóa ERP form.
        </p>
        <ul className={styles.metaList}>
          <li className={styles.metaItem}>
            <span className={styles.metaLabel}>Route</span>
            <span className={styles.metaValue}>{ROUTE}</span>
          </li>
          <li className={styles.metaItem}>
            <span className={styles.metaLabel}>Demo SSOT</span>
            <span className={styles.metaValue}>{DEMO} · FpcCostDeclarePage</span>
          </li>
          <li className={styles.metaItem}>
            <span className={styles.metaLabel}>Feature alias</span>
            <span className={styles.metaValue}>{FEATURE}</span>
          </li>
        </ul>
        <div className={styles.actions}>
          <Link className={`${styles.linkBtn} ${styles.linkBtnPrimary}`} to={DEMO} data-testid={`${testId}-open-demo`}>
            <i className="fas fa-desktop" aria-hidden /> Xem demo
          </Link>
        </div>
      </section>
    </div>
  );
}
